	settings: AppSettings,
	workspaceLayout: WorkspaceLayoutState,
	workspaceExplorer: WorkspaceExplorerState,
	projectRoot: string | null,
	projectHealth: ProjectHealth,
	projectRevision: number,
	projectEntries: WorkspaceEntry[],
	tabs: EditorTab[],
	pendingSaves: DocumentSaveStatus[],
	activeFile: string | null,
	activeBuffer: EditorTab | null,
	activeDocumentDescriptor: DocumentDescriptor | null,
	diagnostics: ProjectDiagnostic[],
	status: string,
	renderError: string | null,
	previewError: string | null,
	previewOpen: boolean,
	audioTransport: AudioTransportSnapshot,
	liveOutput: LiveOutputSnapshot,
	devices: DonderDeviceStatus[],
