/**  A `*.donder` script. */
"script" | "plain";

export type TextPosition = {
	line: number,
	character: number,
};

export type TextRange = {
	start: TextPosition,
	end: TextPosition,
};

export type Transform = {
	position: Point3Meters,
	rotation: Rotation3Degrees,
	scale: Scale3,
};

export type TransitionDecision = "saveAll" | "discard" | "cancel";

export type TransitionRequest = {
	transition: WorkspaceTransition,
	projectEpoch: number,
	projectRevision: number,
	decision: TransitionDecision | null,
};

export type TransitionResult = { type: "applied"; snapshot: AppSnapshot; closeApplication: boolean } | { type: "needsDecision"; snapshot: AppSnapshot; dirtyPaths: string[] } | { type: "cancelled"; snapshot: AppSnapshot };

/**  Progress of a sequence video export, sent while it runs. */
export type VideoExportProgress = { stage: "preparingAudio" } | { stage: "rendering"; completed: number; total: number } | { stage: "saving" };

export type WorkspaceEntry = {
	path: string,
	kind: WorkspaceEntryKind,
	name: string,
	parent: string,
	role: WorkspaceEntryRole,
	operations: WorkspaceOperation[],
	operationExplanation: string | null,
};

export type WorkspaceEntryKind = "directory" | "file";

export type WorkspaceEntryRole = "directory" | "project" | "entrypoint" | "setup" | "controller" | "inputDevice" | "layout" | "fixture" | "patch" | "curve" | "gradient" | "effect" | "operator" | "sequence" | "rig" | "asset" | "file";

export type WorkspaceExplorerState = {
	expandedPaths: string[],
	recentFiles: string[],
};

export type WorkspaceLayoutState = {
	sidebarWidthPx: number,
	inspectorWidthPx: number,
	sidebarCollapsed: boolean,
	inspectorCollapsed: boolean,
	activeSidebarView: SidebarView,
};

export type WorkspaceOperation = "open" | "create" | "rename" | "delete" | "move";

export type WorkspacePathChangeImpact = {
	documents: string[],
	imports: string[],
	assets: string[],
	openFiles: string[],
	recentFiles: string[],
	persistedState: string[],
};

export type WorkspacePathChangePlan = {
	request: WorkspacePathChangeRequest,
	structural: boolean,
	impact: WorkspacePathChangeImpact,
};

export type WorkspacePathChangeRequest = {
	source: string,
	destination: string,
	projectRevision: number,
};

export type WorkspaceTransition = { type: "closeFile"; path: string } | { type: "reloadFile"; path: string } | { type: "reloadProject" } | { type: "openProject"; path: string } | { type: "createProject"; parentPath: string; directoryName: string; initialColor: string } | { type: "copyProject"; parentPath: string; directoryName: string } | { type: "closeApplication" };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

